cells.counterexample:
class Item public method N(): int => 1; end Item;
class Sink
  private _o: Object?;
  public method Keep(o: Object?)
    _o := o;                         // plain parameter: field-store residual admits it
  end Keep;
end Sink;
static class Registry
  public static readonly Sink: Sink := new Sink();
end Registry;
record Pair(Item: Item)
  public override method Equals(other: Object?): bool
    Registry.Sink.Keep(other);       // the T-typed argument arrives boxed at Object?
    return false;
  end Equals;
  public override method GetHashCode(): int => 0;
end Pair;
public static method Run()
  do
    using var it := new Item();
    var ps: Array<Pair> := [new Pair(it)];      // local collection in it's block: admitted (§9.7)
    var hit := ps.Contains(new Pair(it));       // register: Pair has a first-kind member, Equals(Object?)
  end;                                          // it disposed; Registry.Sink holds a boxed Pair borrowing it
end Run;  // direct `new Pair(it).Equals(p)` is rejected (§9.7); via Contains no rule fires

class Keep<T>
  private _v: T?;
  public method Put(x: IReadOnlySpan<int>)
    _v := x as T;     // x's type mentions no type parameter: no §9.7 requirement at any instantiation;
  end Put;            // T is not Object or an interface here; the body is not re-checked
end Keep;

public static method Run(k: Keep<Object>)
  do
    var a: Array<int> := [1, 2, 3];
    k.Put(a.AsSpan());   // admitted: parameter declared IReadOnlySpan<int>, source outlives the call
  end;                   // a disposed; k._v is an Object boxing a span over it (§12.7: ordinary runtime
end Run;                 // test at T = Object). `x as Object` written directly is rejected (§9.7).
// Twins: `case x of t: T => _v := t;`, `sink.Put(x as T)` at ISink<T>, `xs.Add(x as T)` at Array<T>.
// Route 2: Array<IReadOnlySpan<int>> holding a.AsSpan() and a user class implementing
// IReadOnlySpan<int> whose `override Equals(other: Object?)` stores `other`; xs.Contains(...) hands
// it the span (first kind binds Object's Equals at the interface).

routes.counterexample:
class Evil: IReadOnlySpan<int>
  private _seen: Object?;
  public readonly property Length: int => 0;
  public readonly property IsEmpty: bool => true;
  public property [i: int]: int => 0;
  public method IndexOf(value: int): int => -1;
  public method Contains(value: int): bool => false;
  public method SequenceEqual(other: IReadOnlySpan<int>): bool => false;
  public override method Equals(other: Object?): bool  _seen := other; return false;  end Equals;  // cl.2 residual
  public override method GetHashCode(): int => 0;
  public method Peek(): int => (_seen as IReadOnlySpan<int>)![0];
end Evil;

method Run(evil: Evil): int
  do
    using var buf := new OwningBuffer<int>(4);
    var xs: Array<IReadOnlySpan<int>> := [evil];
    var ys: Array<IReadOnlySpan<int>> := [buf.AsReadOnlySpan()];
    var a := xs.Contains(buf.AsReadOnlySpan());  // first kind at IReadOnlySpan<int>: Object's Equals
    var b := ys.Contains(evil);                  // either operand order runs evil.Equals(<span box>)
  end
  return evil.Peek();                            // a span over a disposed buffer, held in an Object? field
end Run;

module M;
class Item
  public constructor() end constructor;
  public method N(): int => 1;
end Item;
record Slot                       // body record, settable member
  public property Item: Item?;
end Slot;
class Grid
  public static method Fill(buf: OwningBuffer<Slot>): int do
    var s := buf.AsSpan();        // Span<Slot>, value-typed T
    do
      using var it := new Item();
      for var b in s do           // §29.2: "a borrow of the slot"
        b.Item := it;             // #5714: holder = root `b`, a loop local;
      end                         //   `it` is in an enclosing block: admitted
    end                           // `it` disposed
    return s[0].Item!.N();        // in place: the caller's buffer holds the dead `it`
  end
end Grid;
